{
  "title": "scim-feature-support-bool",
  "request": "Hey, can we make ScimFeatureSupport evaluate to its 'supported' flag in booleans? Like bool(ScimFeatureSupport(supported=False)) should be False instead of always True.",
  "edits": [
    {
      "path": "langfuse/api/scim/types/scim_feature_support.py",
      "search": "    model_config: typing.ClassVar[pydantic.ConfigDict] = pydantic.ConfigDict(
        extra="allow", frozen=True
    )",
      "replace": "    model_config: typing.ClassVar[pydantic.ConfigDict] = pydantic.ConfigDict(
        extra="allow", frozen=True
    )

    def __bool__(self) -> bool:
        """Allow the model to be used directly in boolean contexts.

        Returns the value of the ``supported`` field so that ``bool(instance)``
        reflects whether the feature is supported.
        """
        return self.supported"
    }
  ],
  "test_path": "tests/unit/test_scim_feature_support_bool.py",
  "test": "import pytest

from langfuse.api.scim.types.scim_feature_support import ScimFeatureSupport

def test_scim_feature_support_bool_true():
    feat = ScimFeatureSupport(supported=True)
    assert bool(feat) is True
    assert feat.supported is True

def test_scim_feature_support_bool_false():
    feat = ScimFeatureSupport(supported=False)
    # Before the change, bool(feat) would be True because objects are truthy.
    assert bool(feat) is False
    assert feat.supported is False"
}
